"""카테1 > 카테2 (shape classification) and the 명자세 index (knowledge classification).

카테2 is the base label: a whole-body shape that people of the target culture (Korean speakers) recognise by name.
Differences that 남녀·노소·에너지 explain are not split into separate 카테2. A name may be an everyday word for the
shape itself (만세, 양반다리, 물구나무); activity or field names (골프 어드레스, 아이 자세) live in 명자세.

명자세 is an auxiliary search index: each field's known poses point at the 카테2 that carries their shape. A known pose
with no fitting 카테2 means the shape list has a hole. The two views are independent and may overlap.

Line format, one entry per line:   이름 | 쪽의 뜻 | 놓임 | 다른 이름(통합·별칭, 쉼표로)
명자세 line format:                 이름[(순간)] | 카테1 > 카테2 | 쪽의 뜻 | 추가 제어(부위=값; …)
Empty columns may be left out. '#' lines are section comments.
"""
from __future__ import annotations

# 동작 이름의 명자세는 어느 순간의 자세인지를 이름 뒤 괄호로 붙인다: 돌려차기(임팩트).
# 임팩트 = 타격·릴리스 순간 또는 점프·동작의 정점. 순간이 없는 이름은 정지 자세다.
